# Sistema de Gestión de Historiales Médicos

Voy a diseñar una aplicación web para gestionar historiales médicos con lector QR, diferentes niveles de permisos y registro de eventos. Usaremos PHP, MySQL, y algunas bibliotecas para el manejo de códigos QR.

## Estructura del Proyecto

Primero, vamos a crear la estructura básica del proyecto:

```bash
mkdir -p sistema_medico/{assets/{css,js,img},config,controllers,models,views,logs,vendor}
```

```bash
cd sistema_medico
```

```bash
touch index.php
```

## Configuración de la Base de Datos

Vamos a crear el archivo de configuración para la conexión a la base de datos:

```php:config/database.php
<?php
class Database {
    private $host = 'localhost';
    private $db_name = 'sistema_medico';
    private $username = 'root'; // Cambiar en producción
    private $password = ''; // Cambiar en producción
    private $conn;

    public function getConnection() {
        $this->conn = null;

        try {
            $this->conn = new PDO('mysql:host=' . $this->host . ';dbname=' . $this->db_name, $this->username, $this->password);
            $this->conn->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
            $this->conn->exec("set names utf8");
        } catch(PDOException $e) {
            echo 'Error de conexión: ' . $e->getMessage();
        }

        return $this->conn;
    }
}
?>
```

## Configuración de Seguridad

Vamos a crear un archivo para manejar la seguridad:

```php:config/security.php
<?php
class Security {
    // Función para limpiar entradas
    public static function sanitize($data) {
        $data = trim($data);
        $data = stripslashes($data);
        $data = htmlspecialchars($data);
        return $data;
    }

    // Función para encriptar contraseñas
    public static function hashPassword($password) {
        return password_hash($password, PASSWORD_BCRYPT, ['cost' => 12]);
    }

    // Función para verificar contraseñas
    public static function verifyPassword($password, $hash) {
        return password_verify($password, $hash);
    }

    // Función para generar token CSRF
    public static function generateCSRFToken() {
        if (!isset($_SESSION['csrf_token'])) {
            $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
        }
        return $_SESSION['csrf_token'];
    }

    // Función para verificar token CSRF
    public static function verifyCSRFToken($token) {
        if (!isset($_SESSION['csrf_token']) || $token !== $_SESSION['csrf_token']) {
            return false;
        }
        return true;
    }
}
?>
```

## Sistema de Logs

Vamos a crear un sistema para registrar todos los eventos:

```php:config/logger.php
<?php
class Logger {
    private $logFile;

    public function __construct() {
        $this->logFile = dirname(__DIR__) . '/logs/app_' . date('Y-m-d') . '.log';

        // Crear directorio de logs si no existe
        if (!file_exists(dirname(__DIR__) . '/logs')) {
            mkdir(dirname(__DIR__) . '/logs', 0755, true);
        }
    }

    public function log($level, $message, $context = []) {
        $date = date('Y-m-d H:i:s');
        $userId = isset($_SESSION['user_id']) ? $_SESSION['user_id'] : 'No autenticado';
        $userRole = isset($_SESSION['role']) ? $_SESSION['role'] : 'N/A';
        $ip = $_SERVER['REMOTE_ADDR'];

        $logMessage = "[$date] [$level] [Usuario: $userId] [Rol: $userRole] [IP: $ip] $message";

        if (!empty($context)) {
            $logMessage .= " Contexto: " . json_encode($context);
        }

        $logMessage .= PHP_EOL;

        file_put_contents($this->logFile, $logMessage, FILE_APPEND);
    }

    public function info($message, $context = []) {
        $this->log('INFO', $message, $context);
    }

    public function warning($message, $context = []) {
        $this->log('WARNING', $message, $context);
    }

    public function error($message, $context = []) {
        $this->log('ERROR', $message, $context);
    }

    public function critical($message, $context = []) {
        $this->log('CRITICAL', $message, $context);
    }
}
?>
```

## Modelos

### Modelo de Usuario

```php:models/User.php
<?php
require_once 'config/database.php';
require_once 'config/security.php';
require_once 'config/logger.php';

class User {
    private $conn;
    private $table_name = "users";
    private $logger;

    public $id;
    public $username;
    public $password;
    public $email;
    public $role; // 'admin', 'medico', 'enfermero'
    public $created_at;

    public function __construct($db) {
        $this->conn = $db;
        $this->logger = new Logger();
    }

    // Crear un nuevo usuario
    public function create() {
        $query = "INSERT INTO " . $this->table_name . " 
                  SET username = :username, 
                      password = :password, 
                      email = :email, 
                      role = :role, 
                      created_at = NOW()";

        $stmt = $this->conn->prepare($query);

        // Sanitizar y encriptar
        $this->username = Security::sanitize($this->username);
        $this->email = Security::sanitize($this->email);
        $this->password = Security::hashPassword($this->password);
        $this->role = Security::sanitize($this->role);

        // Bind
        $stmt->bindParam(":username", $this->username);
        $stmt->bindParam(":password", $this->password);
        $stmt->bindParam(":email", $this->email);
        $stmt->bindParam(":role", $this->role);

        if ($stmt->execute()) {
            $this->id = $this->conn->lastInsertId();
            $this->logger->info("Usuario creado", ["id" => $this->id, "username" => $this->username, "role" => $this->role]);
            return true;
        }

        $this->logger->error("Error al crear usuario", ["username" => $this->username]);
        return false;
    }

    // Verificar si el usuario existe y las credenciales son correctas
    public function login() {
        $query = "SELECT id, username, password, email, role FROM " . $this->table_name . " WHERE username = :username LIMIT 1";
        $stmt = $this->conn->prepare($query);

        $this->username = Security::sanitize($this->username);
        $stmt->bindParam(":username", $this->username);
        $stmt->execute();

        if ($stmt->rowCount() > 0) {
            $row = $stmt->fetch(PDO::FETCH_ASSOC);

            if (Security::verifyPassword($this->password, $row['password'])) {
                $this->id = $row['id'];
                $this->email = $row['email'];
                $this->role = $row['role'];

                $this->logger->info("Inicio de sesión exitoso", ["id" => $this->id, "username" => $this->username]);
                return true;
            }
        }

        $this->logger->warning("Intento de inicio de sesión fallido", ["username" => $this->username]);
        return false;
    }

    // Obtener todos los usuarios (solo para admin)
    public function readAll() {
        $query = "SELECT id, username, email, role, created_at FROM " . $this->table_name;
        $stmt = $this->conn->prepare($query);
        $stmt->execute();

        return $stmt;
    }

    // Actualizar usuario
    public function update() {
        $query = "UPDATE " . $this->table_name . "
                SET username = :username,
                    email = :email,
                    role = :role
                WHERE id = :id";

        $stmt = $this->conn->prepare($query);

        $this->username = Security::sanitize($this->username);
        $this->email = Security::sanitize($this->email);
        $this->role = Security::sanitize($this->role);
        $this->id = Security::sanitize($this->id);

        $stmt->bindParam(":username", $this->username);
        $stmt->bindParam(":email", $this->email);
        $stmt->bindParam(":role", $this->role);
        $stmt->bindParam(":id", $this->id);

        if ($stmt->execute()) {
            $this->logger->info("Usuario actualizado", ["id" => $this->id]);
            return true;
        }

        $this->logger->error("Error al actualizar usuario", ["id" => $this->id]);
        return false;
    }

    // Cambiar contraseña
    public function changePassword() {
        $query = "UPDATE " . $this->table_name . "
                SET password = :password
                WHERE id = :id";

        $stmt = $this->conn->prepare($query);

        $this->password = Security::hashPassword($this->password);
        $this->id = Security::sanitize($this->id);

        $stmt->bindParam(":password", $this->password);
        $stmt->bindParam(":id", $this->id);

        if ($stmt->execute()) {
            $this->logger->info("Contraseña actualizada", ["id" => $this->id]);
            return true;
        }

        $this->logger->error("Error al actualizar contraseña", ["id" => $this->id]);
        return false;
    }

    // Eliminar usuario
    public function delete() {
        $query = "DELETE FROM " . $this->table_name . " WHERE id = :id";
        $stmt = $this->conn->prepare($query);

        $this->id = Security::sanitize($this->id);
        $stmt->bindParam(":id", $this->id);

        if ($stmt->execute()) {
            $this->logger->info("Usuario eliminado", ["id" => $this->id]);
            return true;
        }

        $this->logger->error("Error al eliminar usuario", ["id" => $this->id]);
        return false;
    }
}
?>
```

### Modelo de Paciente

```php:models/Patient.php
<?php
require_once 'config/database.php';
require_once 'config/security.php';
require_once 'config/logger.php';

class Patient {
