    public $direccion;
    public $telefono;
    public $email;
    public $numero_seguro;
    public $grupo_sanguineo;
    public $alergias;
    public $qr_code;
    public $created_at;
    public $updated_at;

    public function __construct($db) {
        $this->conn = $db;
        $this->logger = new Logger();
    }

    // Crear un nuevo paciente
    public function create() {
        $query = "INSERT INTO " . $this->table_name . " 
                  SET nombre = :nombre, 
                      apellidos = :apellidos, 
                      fecha_nacimiento = :fecha_nacimiento, 
                      genero = :genero, 
                      direccion = :direccion, 
                      telefono = :telefono, 
                      email = :email, 
                      numero_seguro = :numero_seguro, 
                      grupo_sanguineo = :grupo_sanguineo, 
                      alergias = :alergias, 
                      qr_code = :qr_code, 
                      created_at = NOW(), 
                      updated_at = NOW()";

        $stmt = $this->conn->prepare($query);

        // Sanitizar
        $this->nombre = Security::sanitize($this->nombre);
        $this->apellidos = Security::sanitize($this->apellidos);
        $this->fecha_nacimiento = Security::sanitize($this->fecha_nacimiento);
        $this->genero = Security::sanitize($this->genero);
        $this->direccion = Security::sanitize($this->direccion);
        $this->telefono = Security::sanitize($this->telefono);
        $this->email = Security::sanitize($this->email);
        $this->numero_seguro = Security::sanitize($this->numero_seguro);
        $this->grupo_sanguineo = Security::sanitize($this->grupo_sanguineo);
        $this->alergias = Security::sanitize($this->alergias);

        // Generar código QR único
        $this->qr_code = uniqid('PAT_', true);

        // Bind
        $stmt->bindParam(":nombre", $this->nombre);
        $stmt->bindParam(":apellidos", $this->apellidos);
        $stmt->bindParam(":fecha_nacimiento", $this->fecha_nacimiento);
        $stmt->bindParam(":genero", $this->genero);
        $stmt->bindParam(":direccion", $this->direccion);
        $stmt->bindParam(":telefono", $this->telefono);
        $stmt->bindParam(":email", $this->email);
        $stmt->bindParam(":numero_seguro", $this->numero_seguro);
        $stmt->bindParam(":grupo_sanguineo", $this->grupo_sanguineo);
        $stmt->bindParam(":alergias", $this->alergias);
        $stmt->bindParam(":qr_code", $this->qr_code);

        if ($stmt->execute()) {
            $this->id = $this->conn->lastInsertId();
            $this->logger->info("Paciente creado", ["id" => $this->id, "nombre" => $this->nombre, "apellidos" => $this->apellidos]);
            return true;
        }

        $this->logger->error("Error al crear paciente", ["nombre" => $this->nombre, "apellidos" => $this->apellidos]);
        return false;
    }

    // Buscar paciente por código QR
    public function findByQR() {
        $query = "SELECT * FROM " . $this->table_name . " WHERE qr_code = :qr_code LIMIT 1";
        $stmt = $this->conn->prepare($query);

        $this->qr_code = Security::sanitize($this->qr_code);
        $stmt->bindParam(":qr_code", $this->qr_code);
        $stmt->execute();

        if ($stmt->rowCount() > 0) {
            $row = $stmt->fetch(PDO::FETCH_ASSOC);

            $this->id = $row['id'];
            $this->nombre = $row['nombre'];
            $this->apellidos = $row['apellidos'];
