        $stmt->bindParam(":id", $this->id);

        if ($stmt->execute()) {
            $this->logger->info("Paciente actualizado", ["id" => $this->id]);
            return true;
        }

        $this->logger->error("Error al actualizar paciente", ["id" => $this->id]);
        return false;
