        $stmt = $this->conn->prepare($query);

        $this->id = Security::sanitize($this->id);
        $stmt->bindParam(":id", $this->id);

        if ($stmt->execute()) {
            $this->logger->info("Paciente eliminado", ["id" => $this->id]);
            return true;
        }

        $this->logger->error("Error al eliminar paciente", ["id" => $this->id]);
        return false;
    }

    // Buscar pacientes por nombre o apellido
    public function search($keywords) {
        $query = "SELECT * FROM " . $this->table_name . " 
                  WHERE nombre LIKE :keywords 
                  OR apellidos LIKE :keywords 
                  OR numero_seguro LIKE :keywords 
                  ORDER BY apellidos, nombre";

        $stmt = $this->conn->prepare($query);

        $keywords = Security::sanitize($keywords);
        $keywords = "%{$keywords}%";
        $stmt->bindParam(":keywords", $keywords);

        $stmt->execute();
        return $stmt;
