### Modelo de Historial Médico

```php:models/MedicalRecord.php
<?php
require_once 'config/database.php';
require_once 'config/security.php';
require_once 'config/logger.php';

class MedicalRecord {
    private $conn;
    private $table_name = "medical_records";
    private $logger;

    public $id;
    public $patient_id;
    public $user_id;
    public $fecha_consulta;
    public $motivo_consulta;
    public $diagnostico;
    public $tratamiento;
    public $observaciones;
    public $signos_vitales;
    public $created_at;
    public $updated_at;

    public function __construct($db) {
        $this->conn = $db;
        $this->logger = new Logger();
    }

    // Crear un nuevo registro médico
    public function create() {
        $query = "INSERT INTO " . $this->table_name . " 
                  SET patient_id = :patient_id, 
                      user_id = :user_id, 
                      fecha_consulta = :fecha_consulta, 
                      motivo_consulta = :motivo_consulta, 
                      diagnostico = :diagnostico, 
                      tratamiento = :tratamiento, 
                      observaciones = :observaciones, 
                      signos_vitales = :signos_vitales, 
                      created_at = NOW(), 
                      updated_at = NOW()";

        $stmt = $this->conn->prepare($query);

        // Sanitizar
        $this->patient_id = Security::sanitize($this->patient_id);
        $this->user_id = Security::sanitize($this->user_id);
        $this->fecha_consulta = Security::sanitize($this->fecha_consulta);
        $this->motivo_consulta = Security::sanitize($this->motivo_consulta);
        $this->diagnostico = Security::sanitize($this->diagnostico);
        $this->tratamiento = Security::sanitize($this->tratamiento);
        $this->observaciones = Security::sanitize($this->observaciones);
        $this->signos_vitales = Security::sanitize($this->signos_vitales);

        // Bind
        $stmt->bindParam(":patient_id", $this->patient_id);
        $stmt->bindParam(":user_id", $this->user_id);
        $stmt->bindParam(":fecha_consulta", $this->fecha_consulta);
        $stmt->bindParam(":motivo_consulta", $this->motivo_consulta);
        $stmt->bindParam(":diagnostico", $this->diagnostico);
        $stmt->bindParam(":tratamiento", $this->tratamiento);
        $stmt->bindParam(":observaciones", $this->observaciones);
        $stmt->bindParam(":signos_vitales", $this->signos_vitales);

        if ($stmt->execute()) {
            $this->id = $this->conn->lastInsertId();
            $this->logger->info("Registro médico creado", ["id" => $this->id, "patient_id" => $this->patient_id, "user_id" => $this->user_id]);
            return true;
        }

        $this->logger->error("Error al crear registro médico", ["patient_id" => $this->patient_id, "user_id" => $this->user_id]);
        return false;
    }

    // Obtener un registro médico por ID
    public function readOne() {
        $query = "SELECT * FROM " . $this->table_name . " WHERE id = :id LIMIT 1";
        $stmt = $this->conn->prepare($query);

        $this->id = Security::sanitize($this->id);
        $stmt->bindParam(":id", $this->id);
        $stmt->execute();

        if ($stmt->rowCount() > 0) {
            $row = $stmt->fetch(PDO::FETCH_ASSOC);

            $this->patient_id = $row['patient_id'];
            $this->user_id = $row['user_id'];
            $this->fecha_consulta = $row['fecha_consulta'];
            $this->motivo_consulta = $row['motivo_consulta'];
            $this->diagnostico = $row['diagnostico'];
            $this->tratamiento = $row['tratamiento'];
            $this->observaciones = $row['observaciones'];
            $this->signos_vitales = $row['signos_vitales'];
            $this->created_at = $row['created_at'];
            $this->updated_at = $row['updated_at'];

            return true;
        }

        return false;
    }

    // Obtener todos los registros médicos de un paciente
    public function readByPatient() {
        $query = "SELECT mr.*, u.username as doctor_name 
                  FROM " . $this->table_name . " mr
                  LEFT JOIN users u ON mr.user_id = u.id
                  WHERE mr.patient_id = :patient_id 
                  ORDER BY mr.fecha_consulta DESC";

        $stmt = $this->conn->prepare($query);

        $this->patient_id = Security::sanitize($this->patient_id);
        $stmt->bindParam(":patient_id", $this->patient_id);

        $stmt->execute();
        return $stmt;
    }

    // Actualizar registro médico
    public function update() {
        $query = "UPDATE " . $this->table_name . "
                SET fecha_consulta = :fecha_consulta,
                    motivo_consulta = :motivo_consulta,
                    diagnostico = :diagnostico,
                    tratamiento = :tratamiento,
                    observaciones = :observaciones,
                    signos_vitales = :signos_vitales,
                    updated_at = NOW()
                WHERE id = :id";

        $stmt = $this->conn->prepare($query);

        // Sanitizar
        $this->fecha_consulta = Security::sanitize($this->fecha_consulta);
        $this->motivo_consulta = Security::sanitize($this->motivo_consulta);
        $this->diagnostico = Security::sanitize($this->diagnostico);
        $this->tratamiento = Security::sanitize($this->tratamiento);
        $this->observaciones = Security::sanitize($this->observaciones);
        $this->signos_vitales = Security::sanitize($this->signos_vitales);
        $this->id = Security::sanitize($this->id);

        // Bind
