    }

    public function checkPermission($requiredRole) {
        if (!$this->isLoggedIn()) {
            return false;
        }

        $userRole = $this->getCurrentUserRole();

        // Si el usuario es admin, tiene acceso a todo
        if ($userRole === 'admin') {
            return true;
        }

        // Verificar si el rol del usuario coincide con el rol requerido
        if ($userRole === $requiredRole) {
            return true;
        }

        // Casos especiales: los médicos pueden ver lo que ven los enfermeros
        if ($userRole === 'medico' && $requiredRole === 'enfermero') {
            return true;
        }

        return false;
