    public function createUser($username, $password, $email, $role) {
        // Verificar permisos
        if (!$this->auth->checkPermission('admin')) {
            $this->logger->warning("Intento no autorizado de crear usuario", [
                "attempted_by" => $this->auth->getCurrentUserId()
            ]);
            return ["success" => false, "message" => "No tiene permisos para realizar esta acción"];
        }

        $user = new User($this->db);

        // Validar datos
        if (empty($username) || empty($password) || empty($email) || empty($role)) {
            return ["success" => false, "message" => "Todos los campos son obligatorios"];
        }

        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            return ["success" => false, "message" => "Email inválido"];
        }

        if (!in_array($role, ['admin', 'medico', 'enfermero'])) {
            return ["success" => false, "message" => "Rol inválido"];
        }

        // Asignar valores
        $user->username = $username;
        $user->password = $password;
        $user->email = $email;
        $user->role = $role;

        // Crear usuario
        if ($user->create()) {
            return ["success" => true, "message" => "Usuario creado con éxito", "user_id" => $user->id];
        } else {
            return ["success" => false, "message" => "No se pudo crear el usuario"];
        }
    }

