        // Verificar permisos
        if (!$this->auth->checkPermission('admin')) {
            $this->logger->warning("Intento no autorizado de listar usuarios", [
                "attempted_by" => $this->auth->getCurrentUserId()
            ]);
            return ["success" => false, "message" => "No tiene permisos para realizar esta acción"];
        }

        $user = new User($this->db);
        $stmt = $user->readAll();
        $users = [];

        while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {
            $users[] = [
                "id" => $row['id'],
                "username" => $row['username'],
                "email" => $row['email'],
                "role" => $row['role'],
                "created_at" => $row['created_at']
            ];
        }

        return ["success" => true, "users" => $users];
    }

    public function updateUser($id, $username, $email, $role) {
        // Verificar permisos
        if (!$this->auth->checkPermission('admin')) {
            $this->logger->warning("Intento no autorizado de actualizar usuario", [
                "attempted_by" => $this->auth->getCurrentUserId(),
                "target_user" => $id
            ]);
            return ["success" => false, "message" => "No tiene permisos para realizar esta acción"];
        }

        $user = new User($this->db);

        // Validar datos
        if (empty($username) || empty($email) || empty($role)) {
            return ["success" => false, "message" => "Todos los campos son obligatorios"];
        }

        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            return ["success" => false, "message" => "Email inválido"];
        }

        if (!in_array($role, ['admin', 'medico', 'enfermero'])) {
            return ["success" => false, "message" => "Rol inválido"];
        }

        // Asignar valores
        $user->id = $id;
        $user->username = $username;
        $user->email = $email;
        $user->role = $role;

        // Actualizar usuario
        if ($user->update()) {
            return ["success" => true, "message" => "Usuario actualizado con éxito"];
        } else {
            return ["success" => false, "message" => "No se pudo actualizar el usuario"];
        }
