                "attempted_by" => $this->auth->getCurrentUserId(),
                "target_user" => $id
            ]);
            return ["success" => false, "message" => "No tiene permisos para realizar esta acción"];
        }

        $user = new User($this->db);
        $user->id = $id;

        // Eliminar usuario
        if ($user->delete()) {
            return ["success" => true, "message" => "Usuario eliminado con éxito"];
        } else {
            return ["success" => false, "message" => "No se pudo eliminar el usuario"];
