        while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {
            $records[] = [
                "id" => $row['id'],
                "fecha_consulta" => $row['fecha_consulta'],
                "motivo_consulta" => $row['motivo_consulta'],
                "diagnostico" => $row['diagnostico'],
                "doctor_name" => $row['doctor_name'],
                "created_at" => $row['created_at']
            ];
        }

        return ["success" => true, "records" => $records];
    }

    public function updateMedicalRecord($id, $data) {
        // Verificar permisos (solo médicos pueden actualizar registros)
        if (!$this->auth->checkPermission('medico')) {
            $this->logger->warning("Intento no autorizado de actualizar registro médico", [
                "attempted_by" => $this->auth->getCurrentUserId(),
                "record_id" => $id
            ]);
            return ["success" => false, "message" => "No tiene permisos para realizar esta acción"];
        }

        $record = new MedicalRecord($this->db);
        $record->id = $id;

        // Verificar si el registro existe
        if (!$record->readOne()) {
            return ["success" => false, "message" => "Registro médico no encontrado"];
        }

        // Validar datos básicos
        if (empty($data['fecha_consulta']) || empty($data['motivo_consulta'])) {
            return ["success" => false, "message" => "Fecha y motivo de consulta son obligatorios"];
        }

        // Asignar valores
        $record->fecha_consulta = $data['fecha_consulta'];
        $record->motivo_consulta = $data['motivo_consulta'];
        $record->diagnostico = $data['diagnostico'] ?? '';
        $record->tratamiento = $data['tratamiento'] ?? '';
        $record->observaciones = $data['observaciones'] ?? '';
        $record->signos_vitales = $data['signos_vitales'] ?? '';

        // Actualizar registro médico
        if ($record->update()) {
            return ["success" => true, "message" => "Registro médico actualizado con éxito"];
        } else {
            return ["success" => false, "message" => "No se pudo actualizar el registro médico"];
        }
    }

    public function deleteMedicalRecord($id) {
        // Verificar permisos (solo admin y médicos pueden eliminar registros)
        if (!$this->auth->checkPermission('admin') && !$this->auth->checkPermission('medico')) {
            $this->logger->warning("Intento no autorizado de eliminar registro médico", [
                "attempted_by" => $this->auth->getCurrentUserId(),
                "record_id" => $id
            ]);
            return ["success" => false, "message" => "No tiene permisos para realizar esta acción"];
        }

        $record = new MedicalRecord($this->db);
        $record->id = $id;

        // Eliminar registro médico
        if ($record->delete()) {
            return ["success" => true, "message" => "Registro médico eliminado con éxito"];
        } else {
            return ["success" => false, "message" => "No se pudo eliminar el registro médico"];
        }
    }
}
